AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_015oMePoeP1kubBL6dSbiL7A', arguments={'file_text': ':root {
  --bg-0: #0b0c10;
  --bg-1: #111319;
  --bg-2: #171a22;
  --bg-3: #1f232d;
  --line: #2a2f3a;
  --line-strong: #3a4150;
  --text: #eef0f4;
  --text-muted: #a4abbb;
  --text-dim: #7a8294;
  --accent: #e8c690;        /* warm champagne */
  --accent-strong: #f3d6a6;
  --accent-ink: #1a1408;
  --danger: #ff7a7a;
  --success: #7fd9a4;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-1: 0 1px 0 rgba(255,255,255,0.04) inset, 0 12px 30px rgba(0,0,0,0.45);
  --shadow-2: 0 1px 0 rgba(255,255,255,0.05) inset, 0 24px 60px rgba(0,0,0,0.55);
  --container: 1200px;
  --focus: 0 0 0 2px var(--bg-0), 0 0 0 4px var(--accent);
}

* { box-sizing: border-box; }

html { color-scheme: dark; }

body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: var(--text);
  background: var(--bg-0);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent); }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}
button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 8px 14px;
  border-radius: 6px;
  font-weight: 600;
  z-index: 1000;
  transition: top 0.15s ease;
}
.skip-link:focus { top: 12px; color: var(--accent-ink); }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 12, 16, 0.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-row {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 68px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  font-weight: 700;
  letter-spacing: 0.02em;
}
.brand:hover { color: var(--text); }
.brand-mark { color: var(--accent); }
.brand-name { font-size: 1.05rem; }

.primary-nav {
  flex: 1;
  display: flex;
  justify-content: center;
}
.primary-nav ul {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 0.94rem;
  font-weight: 500;
  transition: color 0.15s, background 0.15s;
}
.primary-nav a:hover {
  color: var(--text);
  background: var(--bg-2);
}

.header-actions { display: inline-flex; gap: 4px; }
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s, background 0.15s;
}
.icon-btn:hover { color: var(--text); background: var(--bg-2); }
.cart-count {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  font-size: 11px;
  font-weight: 700;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* ---------- Common ---------- */
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--text-dim);
  margin: 0 0 12px;
}
.eyebrow-accent { color: var(--accent); }

h2 {
  font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.1rem);
  letter-spacing: -0.01em;
  margin: 0;
  font-weight: 600;
}
h3 { margin: 0; font-weight: 600; letter-spacing: -0.005em; }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.section-link {
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.94rem;
}
.section-link:hover { color: var(--accent); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  letter-spacing: 0.005em;
  transition: transform 0.1s ease, background 0.15s, color 0.15s, border-color 0.15s;
  cursor: pointer;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); color: var(--accent-ink); }
.btn-ghost {
  border-color: var(--line-strong);
  color: var(--text);
}
.btn-ghost:hover { background: var(--bg-2); color: var(--text); border-color: var(--text-dim); }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  font-weight: 600;
  font-size: 0.95rem;
}
.link-arrow:hover { color: var(--accent-strong); }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 64px 0 96px;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: -10% -10% auto -10%;
  height: 70%;
  background:
    radial-gradient(60% 60% at 80% 20%, rgba(232, 198, 144, 0.10), transparent 60%),
    radial-gradient(40% 40% at 10% 30%, rgba(120, 130, 200, 0.08), transparent 60%);
  pointer-events: none;
}
.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 64px;
  align-items: center;
}
.hero-copy { max-width: 560px; }
.hero-title {
  font-size: clamp(2.4rem, 1.6rem + 3.5vw, 4.4rem);
  line-height: 1.02;
  letter-spacing: -0.025em;
  font-weight: 600;
  margin: 0 0 22px;
}
.hero-lede {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin: 0 0 32px;
  max-width: 48ch;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 48px; }

.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin: 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
}
.hero-stats > div { min-width: 0; }
.hero-stats dt {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text-dim);
}
.hero-stats dd {
  margin: 4px 0 0;
  font-weight: 600;
  color: var(--text);
}

/* Hero art (decorative card stack) */
.hero-art {
  position: relative;
  height: 480px;
}
.hero-card {
  position: absolute;
  border-radius: 18px;
  border: 1px solid var(--line);
  box-shadow: var(--shadow-2);
  overflow: hidden;
}
.hc-1 {
  inset: 40px 60px 60px 0;
  background:
    linear-gradient(135deg, #2a2018 0%, #100c08 60%),
    radial-gradient(circle at 30% 20%, rgba(232, 198, 144, 0.4), transparent 50%);
  background-blend-mode: screen;
}
.hc-1::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(70% 50% at 30% 30%, rgba(232,198,144,0.18), transparent 60%);
}
.hc-2 {
  width: 60%;
  aspect-ratio: 3/4;
  top: 0;
  right: 0;
  background:
    linear-gradient(150deg, #1f2533, #0f131c 80%),
    radial-gradient(circle at 70% 80%, rgba(120,140,220,0.4), transparent 50%);
  background-blend-mode: screen;
}
.hc-3 {
  width: 38%;
  aspect-ratio: 1/1;
  bottom: 0;
  right: 30%;
  background:
    linear-gradient(135deg, #1c1d22, #0a0b10);
  border-radius: 50%;
}
.hero-glow {
  position: absolute;
  inset: 20% 30%;
  background: radial-gradient(closest-side, rgba(232, 198, 144, 0.18), transparent);
  filter: blur(20px);
  pointer-events: none;
}

/* ---------- Categories ---------- */
.categories { padding: 24px 0 56px; }
.category-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}
.category-list a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 18px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  font-weight: 500;
  color: var(--text);
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}
.category-list a:hover {
  background: var(--bg-2);
  border-color: var(--line-strong);
  color: var(--text);
}
.cat-emoji {
  font-size: 1.25rem;
  line-height: 1;
}

/* ---------- Featured products ---------- */
.featured { padding: 56px 0; }

.filter-group {
  display: inline-flex;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  gap: 2px;
}
.filter-group [role="tab"] {
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-muted);
  transition: background 0.15s, color 0.15s;
}
.filter-group [role="tab"]:hover { color: var(--text); }
.filter-group [role="tab"][aria-selected="true"] {
  background: var(--accent);
  color: var(--accent-ink);
}

.product-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 22px;
}
.product {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.15s, transform 0.15s;
  position: relative;
}
.product:hover {
  border-color: var(--line-strong);
  transform: translateY(-2px);
}
.product-art {
  aspect-ratio: 4/5;
  position: relative;
  overflow: hidden;
}
.product-art::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.4));
}
.product-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: inline-flex;
  gap: 6px;
  z-index: 2;
}
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--bg-3);
  color: var(--text);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid var(--line);
  text-transform: uppercase;
}
.badge-discount { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.badge-new { background: var(--bg-3); color: var(--accent); border-color: var(--line-strong); }

.product-wish {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: rgba(11, 12, 16, 0.6);
  backdrop-filter: blur(10px);
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  border: 1px solid var(--line);
  transition: color 0.15s, background 0.15s;
}
.product-wish:hover { color: var(--accent); background: rgba(11,12,16,0.85); }
.product-wish[aria-pressed="true"] { color: var(--accent); }

.product-body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
  margin: 0;
}
.product-name a {
  color: var(--text);
}
.product-name a::after {
  content: '';
  position: absolute;
  inset: 0;
}
.product-name a:hover { color: var(--accent); }
.product-meta {
  margin-top: auto;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-top: 10px;
  gap: 10px;
}
.price { font-weight: 700; font-size: 1.05rem; }
.price-was {
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.85rem;
  font-weight: 500;
  margin-left: 6px;
}
.rating {
  font-size: 0.82rem;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.rating .star { color: var(--accent); }

/* Product art variants — abstract gradients standing in for imagery */
.pa-1 { background: linear-gradient(140deg, #5b4a38, #1d1610 70%); }
.pa-2 { background: linear-gradient(140deg, #2a3142, #0f131c 70%); }
.pa-3 { background: linear-gradient(140deg, #3b3024, #100c08 70%); }
.pa-4 { background: linear-gradient(140deg, #2c3528, #0e120c 70%); }
.pa-5 { background: linear-gradient(140deg, #44323a, #18101a 70%); }
.pa-6 { background: linear-gradient(140deg, #2b2f3c, #10131a 70%); }
.pa-7 { background: linear-gradient(140deg, #4a3d2a, #161108 70%); }
.pa-8 { background: linear-gradient(140deg, #312b3c, #100d18 70%); }
.product-art .glyph {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  opacity: 0.65;
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.5));
}

/* ---------- Deals ---------- */
.deals {
  padding: 64px 0;
  background:
    linear-gradient(180deg, transparent, rgba(255,255,255,0.015) 50%, transparent),
    var(--bg-0);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.deal-timer {
  margin: 0;
  color: var(--text-muted);
  font-weight: 500;
}
#deal-countdown {
  font-variant-numeric: tabular-nums;
  background: var(--bg-2);
  border: 1px solid var(--line);
  padding: 6px 12px;
  border-radius: 8px;
  color: var(--accent);
  font-weight: 700;
  margin-left: 6px;
}

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 22px;
}
.deal {
  position: relative;
  border: 1px solid var(--line);
  background: var(--bg-1);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-height: 320px;
  transition: border-color 0.15s, transform 0.15s;
}
.deal:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.deal-feature {
  grid-row: span 2;
  min-height: 480px;
  display: grid;
  grid-template-rows: 1fr auto;
}
.deal-art {
  position: relative;
  flex: 1;
  background: linear-gradient(160deg, #2c3142, #0e1018 75%);
  overflow: hidden;
}
.deal-art-2 {
  background: linear-gradient(160deg, #3b2e22, #100b06 75%);
  min-height: 160px;
}
.deal-art-3 {
  background: linear-gradient(160deg, #2f3a30, #0d120e 75%);
  min-height: 160px;
}
.deal-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}
.ds-1 {
  width: 60%;
  aspect-ratio: 1;
  top: -10%;
  right: -10%;
  background: radial-gradient(closest-side, rgba(232,198,144,0.5), transparent);
}
.ds-2 {
  width: 40%;
  aspect-ratio: 1;
  bottom: -10%;
  left: 10%;
  background: radial-gradient(closest-side, rgba(120,140,200,0.45), transparent);
}
.deal-body {
  padding: 22px 24px 24px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
}
.deal-feature .deal-body { padding: 28px 28px 32px; }
.deal-desc {
  margin: 0 0 6px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.deal-body h3 {
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}
.deal-feature .deal-body h3 { font-size: 1.6rem; }

/* ---------- Editorial ---------- */
.editorial { padding: 72px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 22px;
}
.story {
  border: 1px solid var(--line);
  background: var(--bg-1);
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  transition: border-color 0.15s, transform 0.15s;
}
.story:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.story-link {
  display: block;
  color: var(--text);
  height: 100%;
}
.story-link:hover { color: var(--text); }
.story-link:hover h3 { color: var(--accent); }

.story-art {
  aspect-ratio: 16 / 10;
  background: var(--bg-3);
  border-bottom: 1px solid var(--line);
}
.sa-1 { background: linear-gradient(140deg, #3a2e1f, #0c0905 70%); }
.sa-2 { background: linear-gradient(140deg, #2c344a, #0d1018 70%); }
.sa-3 { background: linear-gradient(140deg, #2a3528, #0c1108 70%); }
.sa-4 { background: linear-gradient(140deg, #3a2630, #100a0e 70%); }

.story-link h3 {
  padding: 0 22px;
  margin: 14px 0 8px;
  font-size: 1.15rem;
  line-height: 1.3;
  transition: color 0.15s;
}
.story-link p {
  padding: 0 22px;
  margin: 0 0 18px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.story-meta {
  padding: 18px 22px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  color: var(--text-dim);
}
.tag {
  background: var(--bg-3);
  color: var(--accent);
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-weight: 600;
  border: 1px solid var(--line-strong);
}
.story-author {
  display: block;
  padding: 0 22px 22px;
  color: var(--text-dim);
  font-size: 0.85rem;
}

.story-lead {
  grid-row: span 2;
}
.story-lead .story-art { aspect-ratio: 4 / 5; min-height: 280px; }
.story-lead h3 { font-size: 1.6rem; line-height: 1.2; }

/* ---------- Newsletter ---------- */
.newsletter {
  padding: 72px 0 88px;
  background:
    radial-gradient(60% 100% at 50% 0%, rgba(232,198,144,0.06), transparent 70%),
    var(--bg-0);
  border-top: 1px solid var(--line);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter h2 { font-size: clamp(1.6rem, 1.2rem + 1.4vw, 2.2rem); }
.newsletter p { color: var(--text-muted); margin: 10px 0 0; max-width: 46ch; }
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
}
.newsletter-form input {
  background: var(--bg-1);
  border: 1px solid var(--line-strong);
  color: var(--text);
  padding: 14px 18px;
  border-radius: 999px;
  font: inherit;
  width: 100%;
  min-width: 0;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgba(232,198,144,0.25); }
.form-status {
  grid-column: 1 / -1;
  margin: 4px 4px 0;
  font-size: 0.9rem;
  color: var(--text-muted);
  min-height: 1.2em;
}
.form-status.is-success { color: var(--success); }
.form-status.is-error { color: var(--danger); }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--bg-1);
  border-top: 1px solid var(--line);
  padding: 56px 0 28px;
  color: var(--text-muted);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 36px;
  border-bottom: 1px solid var(--line);
}
.footer-brand .brand-name { color: var(--text); font-size: 1.15rem; font-weight: 700; }
.footer-brand p { margin: 8px 0 0; max-width: 32ch; }
.site-footer h2 {
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin: 0 0 14px;
  color: var(--text);
  font-weight: 600;
}
.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.site-footer a:hover { color: var(--accent); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding-top: 22px;
  font-size: 0.85rem;
  color: var(--text-dim);
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; gap: 32px; }
  .hero-art { height: 360px; max-width: 520px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-list { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: span 2; grid-row: auto; min-height: 360px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-column: span 2; grid-row: auto; }
  .story-lead .story-art { aspect-ratio: 16/8; min-height: 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  .header-row { gap: 12px; height: 60px; }
  .primary-nav { display: none; }
  .hero { padding: 40px 0 56px; }
  .hero-stats { grid-template-columns: 1fr; gap: 12px; }
  .hero-stats > div { display: flex; justify-content: space-between; align-items: baseline; }
  .hero-stats dd { margin: 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .category-list { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: auto; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
  .newsletter-form { grid-template-columns: 1fr; }
  .section-head { gap: 12px; }
  .filter-group { overflow-x: auto; max-width: 100%; }
}

@media (max-width: 380px) {
  .product-grid { grid-template-columns: 1fr; }
  .category-list { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

@media (forced-colors: active) {
  .btn-primary, .badge-discount, .cart-count, .skip-link {
    forced-color-adjust: none;
  }
  .product, .deal, .story, .category-list a, .filter-group {
    border-color: CanvasText;
  }
}
