@@ -1,0 +1,885 @@
+:root {
+  --bg-0: #0b0c10;
+  --bg-1: #111319;
+  --bg-2: #171a22;
+  --bg-3: #1f232d;
+  --line: #2a2f3a;
+  --line-strong: #3a4150;
+  --text: #eef0f4;
+  --text-muted: #a4abbb;
+  --text-dim: #7a8294;
+  --accent: #e8c690;        /* warm champagne */
