+}
+.hero-glow {
+  position: absolute;
+  inset: 20% 30%;
+  background: radial-gradient(closest-side, rgba(232, 198, 144, 0.18), transparent);
+  filter: blur(20px);
+  pointer-events: none;
+}
+
+/* ---------- Categories ---------- */
+.categories { padding: 24px 0 56px; }
+.category-list {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 14px;
+}
+.category-list a {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 16px 18px;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  font-weight: 500;
+  color: var(--text);
+  transition: background 0.15s, border-color 0.15s, transform 0.1s;
+}
+.category-list a:hover {
+  background: var(--bg-2);
+  border-color: var(--line-strong);
+  color: var(--text);
+}
+.cat-emoji {
+  font-size: 1.25rem;
+  line-height: 1;
+}
+
+/* ---------- Featured products ---------- */
+.featured { padding: 56px 0; }
+
+.filter-group {
+  display: inline-flex;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  padding: 4px;
+  gap: 2px;
+}
+.filter-group [role="tab"] {
+  padding: 8px 16px;
+  border-radius: 999px;
+  font-size: 0.88rem;
+  font-weight: 500;
+  color: var(--text-muted);
+  transition: background 0.15s, color 0.15s;
+}
+.filter-group [role="tab"]:hover { color: var(--text); }
+.filter-group [role="tab"][aria-selected="true"] {
+  background: var(--accent);
+  color: var(--accent-ink);
+}
+
+.product-grid {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 22px;
+}
+.product {
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.15s, transform 0.15s;
+  position: relative;
+}
+.product:hover {
+  border-color: var(--line-strong);
+  transform: translateY(-2px);
+}
+.product-art {
+  aspect-ratio: 4/5;
+  position: relative;
+  overflow: hidden;
+}
+.product-art::before {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.4));
+}
+.product-badges {
+  position: absolute;
+  top: 12px;
+  left: 12px;
+  display: inline-flex;
+  gap: 6px;
+  z-index: 2;
+}
+.badge {
+  display: inline-block;
+  padding: 4px 10px;
+  border-radius: 999px;
+  background: var(--bg-3);
+  color: var(--text);
+  font-size: 0.72rem;
+  font-weight: 600;
+  letter-spacing: 0.04em;
+  border: 1px solid var(--line);
+  text-transform: uppercase;
+}
+.badge-discount { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+.badge-new { background: var(--bg-3); color: var(--accent); border-color: var(--line-strong); }
+
+.product-wish {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  width: 36px;
+  height: 36px;
+  border-radius: 999px;
+  background: rgba(11, 12, 16, 0.6);
+  backdrop-filter: blur(10px);
+  color: var(--text);
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  z-index: 2;
+  border: 1px solid var(--line);
+  transition: color 0.15s, background 0.15s;
+}
+.product-wish:hover { color: var(--accent); background: rgba(11,12,16,0.85); }
+.product-wish[aria-pressed="true"] { color: var(--accent); }
+
+.product-body {
+  padding: 16px 16px 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 0.74rem;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  color: var(--text-dim);
+}
+.product-name {
+  font-size: 1rem;
+  font-weight: 600;
+  line-height: 1.3;
+  margin: 0;
+}
+.product-name a {
+  color: var(--text);
+}
+.product-name a::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+}
+.product-name a:hover { color: var(--accent); }
+.product-meta {
+  margin-top: auto;
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  padding-top: 10px;
+  gap: 10px;
