}
.product-name a::after {
  content: '';
  position: absolute;
  inset: 0;
}
.product-name a:hover { color: var(--accent); }
.product-meta {
  margin-top: auto;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-top: 10px;
  gap: 10px;
