}
.rating .star { color: var(--accent); }

/* Product art variants — abstract gradients standing in for imagery */
.pa-1 { background: linear-gradient(140deg, #5b4a38, #1d1610 70%); }
.pa-2 { background: linear-gradient(140deg, #2a3142, #0f131c 70%); }
.pa-3 { background: linear-gradient(140deg, #3b3024, #100c08 70%); }
.pa-4 { background: linear-gradient(140deg, #2c3528, #0e120c 70%); }
.pa-5 { background: linear-gradient(140deg, #44323a, #18101a 70%); }
.pa-6 { background: linear-gradient(140deg, #2b2f3c, #10131a 70%); }
.pa-7 { background: linear-gradient(140deg, #4a3d2a, #161108 70%); }
.pa-8 { background: linear-gradient(140deg, #312b3c, #100d18 70%); }
.product-art .glyph {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
