  border: 1px solid var(--line);
  padding: 6px 12px;
  border-radius: 8px;
  color: var(--accent);
  font-weight: 700;
  margin-left: 6px;
}

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 22px;
}
.deal {
  position: relative;
  border: 1px solid var(--line);
  background: var(--bg-1);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-height: 320px;
  transition: border-color 0.15s, transform 0.15s;
}
.deal:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.deal-feature {
  grid-row: span 2;
  min-height: 480px;
  display: grid;
  grid-template-rows: 1fr auto;
}
.deal-art {
  position: relative;
  flex: 1;
  background: linear-gradient(160deg, #2c3142, #0e1018 75%);
  overflow: hidden;
}
.deal-art-2 {
  background: linear-gradient(160deg, #3b2e22, #100b06 75%);
  min-height: 160px;
}
.deal-art-3 {
  background: linear-gradient(160deg, #2f3a30, #0d120e 75%);
  min-height: 160px;
}
.deal-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}
.ds-1 {
  width: 60%;
  aspect-ratio: 1;
  top: -10%;
  right: -10%;
  background: radial-gradient(closest-side, rgba(232,198,144,0.5), transparent);
}
.ds-2 {
  width: 40%;
  aspect-ratio: 1;
  bottom: -10%;
  left: 10%;
  background: radial-gradient(closest-side, rgba(120,140,200,0.45), transparent);
}
.deal-body {
  padding: 22px 24px 24px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
}
.deal-feature .deal-body { padding: 28px 28px 32px; }
.deal-desc {
  margin: 0 0 6px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.deal-body h3 {
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}
.deal-feature .deal-body h3 { font-size: 1.6rem; }

/* ---------- Editorial ---------- */
.editorial { padding: 72px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 22px;
}
.story {
  border: 1px solid var(--line);
